import type { PluginRegisterFn } from '@tuucho/plugin-sdk';
import { CORE_OPENING_FILTERS, peekPluginService } from '@tuucho/plugin-sdk';

const register: PluginRegisterFn = async (api) => {
  api.addFilter(CORE_OPENING_FILTERS.profile, (entries) => [
    ...entries,
    { id: 'your-profile', pluginId: api.pluginId, title: 'Your page', href: '/your-page' },
  ]);
  api.registerPluginService(api.pluginId, { ping: () => 'ok' });
  api.registerHttpMount({ scope: 'admin', path: '/your-page', router: yourRouter });
};
export { register };
export default register;

